import{_ as r,o,c as e,a6 as a}from"./chunks/framework.BrkgobfX.js";const c=JSON.parse('{"title":"威胁建模：你到底在防谁","description":"不做威胁建模的安全工作是在拜神——四类攻击者的动机与手法截然不同，防住脚本小子的措施对定向攻击毫无意义。用一张表把「防谁、护什么、丢了多疼」问清楚。","frontmatter":{"title":"威胁建模：你到底在防谁","description":"不做威胁建模的安全工作是在拜神——四类攻击者的动机与手法截然不同，防住脚本小子的措施对定向攻击毫无意义。用一张表把「防谁、护什么、丢了多疼」问清楚。","source":"https://daiw.org/manual/web-security/threat-model"},"headers":[],"relativePath":"manual/computer-programming/web-security/threat-model.md","filePath":"manual/computer-programming/web-security/threat-model.md"}'),d={name:"manual/computer-programming/web-security/threat-model.md"};function n(s,t,l,i,g,h){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="威胁建模-你到底在防谁" tabindex="-1">威胁建模：你到底在防谁 <a class="header-anchor" href="#威胁建模-你到底在防谁" aria-label="Permalink to &quot;威胁建模：你到底在防谁&quot;">​</a></h1><p>不做威胁建模的安全工作是在拜神——四类攻击者的动机与手法截然不同，防住脚本小子的措施对定向攻击毫无意义。用一张表把「防谁、护什么、丢了多疼」问清楚。</p><p>先问一个问题：<strong>你的网站被打了，最坏的结果是什么？</strong></p><p>如果答不上来，后面所有的加固都是在凭感觉花钱。有人给个人博客上了 WAF 高级版，却把数据库密码明文写在 GitHub 公开仓库里——<strong>防线的强度不重要，最薄的那一环才重要</strong>，而找出最薄的那一环，靠的就是威胁建模。</p><h2 id="四类攻击者-四种打法" tabindex="-1">四类攻击者，四种打法 <a class="header-anchor" href="#四类攻击者-四种打法" aria-label="Permalink to &quot;四类攻击者，四种打法&quot;">​</a></h2><p>把「攻击者」当成一个笼统概念是最大的误区。他们的动机、耐心、能力天差地别：</p><table tabindex="0"><thead><tr><th>类型</th><th>动机</th><th>典型手法</th><th>对你的实际威胁</th></tr></thead><tbody><tr><td><strong>自动化扫描器</strong></td><td>广撒网，不针对你</td><td>扫全网 IP，试已知 CVE、默认口令、<code>.git</code> 泄露、<code>.env</code> 泄露</td><td><strong>占实际攻击量的 95% 以上</strong>，也最好防</td></tr><tr><td><strong>脚本小子</strong></td><td>炫技、挂黑页</td><td>用现成工具跑一遍，看哪个洞能进</td><td>主要打没打补丁的老系统</td></tr><tr><td><strong>牟利型</strong></td><td>挖矿、勒索、卖数据、薅羊毛</td><td>找能变现的：接口刷量、数据库脱库、服务器算力</td><td><strong>有电商/会员/积分的站要重点防</strong></td></tr><tr><td><strong>定向攻击</strong></td><td>特定目标，有预算有耐心</td><td>社工、供应链、0day、长期潜伏</td><td>个人站基本遇不上；真遇上了，单靠技术措施挡不住</td></tr></tbody></table><p><strong>这张表最重要的一行是第一行。</strong> 绝大多数「被黑」不是有人盯上了你，而是你的服务器恰好出现在某个扫描器的 IP 段里，恰好开着一个有已知漏洞的服务。</p><p>这带来一个非常实际的结论：</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>把 80% 的精力花在挡住自动化扫描上，投入产出比最高。</strong> 具体就是三件事：<strong>及时打补丁、不要有默认口令、不要泄露不该公开的文件</strong>。这三件事做到位，你已经躲过了绝大多数真实攻击。</p><p>反过来，如果这三件没做，买再贵的 WAF 也只是给一栋没锁门的房子装了监控。</p></div><h2 id="三个问题-问清楚就够了" tabindex="-1">三个问题，问清楚就够了 <a class="header-anchor" href="#三个问题-问清楚就够了" aria-label="Permalink to &quot;三个问题，问清楚就够了&quot;">​</a></h2><p>正式的威胁建模有 STRIDE、PASTA 一堆方法论。对一个网站来说，回答清楚三个问题就足以指导行动：</p><h3 id="一、护什么-资产" tabindex="-1">一、护什么（资产） <a class="header-anchor" href="#一、护什么-资产" aria-label="Permalink to &quot;一、护什么（资产）&quot;">​</a></h3><p>把你系统里「丢了会疼」的东西列出来，按疼的程度排序：</p><table tabindex="0"><thead><tr><th>资产</th><th>例子</th><th>丢了会怎样</th></tr></thead><tbody><tr><td><strong>用户凭据</strong></td><td>密码哈希、会话 token、OAuth refresh token</td><td>最严重：会被拿去撞库，波及用户在别处的账号</td></tr><tr><td><strong>个人信息</strong></td><td>手机号、身份证、地址、订单</td><td>法律责任（个人信息保护法），且不可撤销</td></tr><tr><td><strong>业务数据</strong></td><td>订单、内容、配置</td><td>直接业务损失</td></tr><tr><td><strong>算力与带宽</strong></td><td>服务器、CDN 流量</td><td>被挖矿、被当跳板；账单可能是数量级的</td></tr><tr><td><strong>域名与声誉</strong></td><td>域名本身、搜索排名</td><td>被挂马后搜索引擎标红，恢复要数周</td></tr></tbody></table><p><strong>很多人漏掉最后两项。</strong> 一台被挖矿的云服务器，一个月能烧掉远超你预算的钱；一个被挂了黑帽 SEO 的博客，搜索流量清零。</p><h3 id="二、从哪进-入口" tabindex="-1">二、从哪进（入口） <a class="header-anchor" href="#二、从哪进-入口" aria-label="Permalink to &quot;二、从哪进（入口）&quot;">​</a></h3><p>把所有「外部输入能到达的地方」列出来。不只是表单——凡是攻击者能控制内容的，都是入口：</p><ul><li>HTTP 请求的每个部分：URL 路径、query、Header（含 <code>Host</code>、<code>User-Agent</code>、<code>Referer</code>）、Cookie、body</li><li>文件上传</li><li>第三方回调（支付、OAuth、Webhook）</li><li><strong>你依赖的一切</strong>：npm 包、Docker 基础镜像、CDN 上的第三方脚本</li><li>运维通道：SSH、云控制台、CI/CD、域名注册商后台</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>最后一项是最容易被整体遗忘的。</strong> 你把网站加固到牙齿，但域名注册商账号用的是复用密码、没开二次验证——攻击者直接改 DNS 把域名解析到自己的服务器，你所有的 Nginx 配置、WAF 规则、后端校验<strong>一行都不会被执行</strong>。</p><p><a href="/Front2Full/manual/computer-programming/web-security/registrar-security">下一部分第一篇</a>专门讲这件事，它排在最前面不是偶然。</p></div><h3 id="三、丢了多疼-影响" tabindex="-1">三、丢了多疼（影响） <a class="header-anchor" href="#三、丢了多疼-影响" aria-label="Permalink to &quot;三、丢了多疼（影响）&quot;">​</a></h3><p>同样是「泄露一张表」，泄露文章列表和泄露用户手机号，严重性差几个数量级。用这个粗略的分级排优先级：</p><ul><li><strong>P0 · 不可挽回</strong>：明文密码、身份证、支付信息泄露；服务器被完全控制。</li><li><strong>P1 · 严重但可控</strong>：会话劫持、越权读取他人数据、内容被篡改。</li><li><strong>P2 · 有损失但能恢复</strong>：短时 DoS、资源被薅。</li><li><strong>P3 · 主要是难看</strong>：版本号泄露、目录列表打开。</li></ul><p><strong>修复顺序按 P 级走，不按修复难度走。</strong> 一个花两天修的 P0，优先级高于十个花十分钟修的 P3——虽然后者做起来更有成就感。</p><h2 id="一个真实的例子-给个人博客建模" tabindex="-1">一个真实的例子：给个人博客建模 <a class="header-anchor" href="#一个真实的例子-给个人博客建模" aria-label="Permalink to &quot;一个真实的例子：给个人博客建模&quot;">​</a></h2><p>拿本站这类静态博客做示范，结论可能和你想的不一样：</p><table tabindex="0"><thead><tr><th>项</th><th>结论</th></tr></thead><tbody><tr><td>主要攻击者</td><td>自动化扫描器（几乎唯一）</td></tr><tr><td>核心资产</td><td><strong>域名</strong>（最值钱）、服务器算力、搜索排名</td></tr><tr><td>用户数据</td><td><strong>几乎没有</strong>——纯静态站，没有登录、没有数据库</td></tr><tr><td>最高风险</td><td>域名被劫持；服务器被当矿机；CI/CD 凭据泄露导致投毒</td></tr><tr><td>最不值得投入</td><td>SQL 注入防护（没有数据库）、复杂的 WAF 规则</td></tr></tbody></table><p><strong>注意最后一行。</strong> 一个纯静态站去研究 SQL 注入防护是浪费时间；但很多安全清单会把它列在第一条，因为那些清单不是为你写的。</p><p>反过来，这类站真正的高风险在<strong>供应链</strong>：CI/CD 里的一个 token 泄露，攻击者就能直接改构建产物，往每个页面里插一段脚本。这比任何 XSS 都严重，因为它绕过了所有前端防御。<a href="/Front2Full/manual/computer-programming/web-security/secrets">后面有一整章</a>讲密钥管理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>95% 以上的攻击来自不针对你的自动化扫描，<strong>打补丁 + 无默认口令 + 不泄露文件</strong>能挡住大部分。</li><li>建模只需回答三问：<strong>护什么、从哪进、丢了多疼</strong>。</li><li>入口清单必须包含<strong>运维通道</strong>（注册商、CI/CD、云控制台），它们常被整体遗忘。</li><li>按影响分级排优先级，不要按修复难度。</li></ul><p>下一章把「从哪进」这个问题铺开——跟着一次请求，看它一路经过多少个可以被做手脚的地方。👉 <a href="/Front2Full/manual/computer-programming/web-security/request-journey">一次请求的旅程</a></p>',32)])])}const u=r(d,[["render",n]]);export{c as __pageData,u as default};
